// Service worker for one Learning Hub app (generated by tools/build.py; do not edit the copy in dist/).
// Every app on vardhangs.github.io shares one Cache Storage, so this worker only ever deletes caches whose
// names start with its own app id.
const APP_ID = "science8";
const CACHE = "science8-2deffa3aa6";
const ASSETS = [
  "./",
  "./index.html",
  "./manifest.json",
  "./core/styles.css",
  "./config.js",
  "./core/sound.js",
  "./core/speech.js",
  "./data/voice-clips.js",
  "./core/voice.js",
  "./core/cloud.js",
  "./core/U.js",
  "./core/engine/fig.js",
  "./core/engine/alg.js",
  "./data/sci-common.js",
  "./data/t1.js",
  "./data/t1-living.js",
  "./data/t1-classify.js",
  "./data/t1-microbes.js",
  "./data/t1-plants.js",
  "./data/t2.js",
  "./data/t2-cells.js",
  "./data/t2-organelles.js",
  "./data/t2-transport.js",
  "./data/t3.js",
  "./data/t3-bodyorg.js",
  "./data/t3-interact.js",
  "./data/t3-supply.js",
  "./data/t3-manage.js",
  "./data/t3-control.js",
  "./data/t4.js",
  "./data/t4-patterns.js",
  "./data/t4-plants.js",
  "./data/t4-animals.js",
  "./data/t4-growth.js",
  "./data/t5.js",
  "./data/t5-environment.js",
  "./data/t5-energy.js",
  "./data/t5-cycles.js",
  "./data/t6.js",
  "./data/t6-interactions.js",
  "./data/t6-resilience.js",
  "./data/t6-biodiversity.js",
  "./data/t6-services.js",
  "./data/t7.js",
  "./data/t7-inherit.js",
  "./data/t7-chromosomes.js",
  "./data/t7-protein.js",
  "./data/t7-variation.js",
  "./data/t7-gentech.js",
  "./data/t8.js",
  "./data/t8-early.js",
  "./data/t8-selection.js",
  "./data/t8-process.js",
  "./data/t8-fossils.js",
  "./data/t8-otherevidence.js",
  "./data/topics.js",
  "./data/videos.js",
  "./core/app.js",
  "./icons/icon-180.png",
  "./icons/icon-192.png",
  "./icons/icon-512.png"
];

self.addEventListener("install", (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(ASSETS)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", (e) => {
  e.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(keys.filter((k) => k.startsWith(APP_ID + "-") && k !== CACHE).map((k) => caches.delete(k)))
    ).then(() => self.clients.claim())
  );
});

// Network-first: always try the latest; fall back to the cache only when offline.
self.addEventListener("fetch", (e) => {
  if (e.request.method !== "GET") return;
  const url = new URL(e.request.url);
  // Let the browser stream videos directly (range requests); don't cache them.
  if (url.pathname.includes("/videos/") && url.pathname.endsWith(".mp4")) return;
  // Only this app's own files and the pinned KaTeX files; never Firebase traffic.
  const mine = url.origin === self.location.origin && url.pathname.startsWith(new URL("./", self.location).pathname);
  const katex = url.origin === "https://cdn.jsdelivr.net" && url.pathname.startsWith("/npm/katex@");
  if (!mine && !katex) return;
  e.respondWith(
    fetch(e.request)
      .then((res) => {
        if (res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(e.request, copy)).catch(() => {}); }
        return res;
      })
      .catch(() => caches.match(e.request, { ignoreSearch: true }))
  );
});
